from PIL import Image

def edges(path):
    im = Image.open(path).convert("RGB")
    pix = im.load()
    w,h = im.size
    print("\n====", path)

    # sign reference: white pixels x 430-540, find top y
    tops=[]
    for x in range(430, 540):
        for y in range(180, 280):
            r,g,b=pix[x,y]
            if r>220 and g>220 and b>220:
                tops.append(y)
                break
    if tops:
        print(f"sign top mean {sum(tops)/len(tops):.2f} min {min(tops)} n {len(tops)}")

    # yellow top: scan left and right of spring, x=265-295 and x=350-375
    def yellow_top_at(x):
        for y in range(200, 290):
            r,g,b=pix[x,y]
            if r>160 and g>120 and b<110 and r>b+80:
                return y
        return None

    for name, x0, x1 in [("left", 260, 295), ("right", 350, 380)]:
        ys=[yellow_top_at(x) for x in range(x0, x1)]
        ys=[y for y in ys if y]
        if ys:
            print(f"yellow top {name}: mean {sum(ys)/len(ys):.2f} min {min(ys)} max {max(ys)} n {len(ys)}")

    # platen: find bright white region near x=310-340, y=180-230
    # top edge: first row where mean L > 180
    def strip_L(y, x0, x1):
        s=0; n=0
        for x in range(x0,x1):
            r,g,b=pix[x,y]
            s += 0.3*r+0.59*g+0.11*b
            n+=1
        return s/n

    print("platen strip x=305-335 L profile y=190-230")
    for y in range(190, 235):
        L=strip_L(y, 305, 335)
        print(f"  y={y} L={L:.1f}")

    # spring left/right edges at several y to get width for scale
    print("spring width at y=225")
    dark=[]
    for x in range(270, 400):
        r,g,b=pix[x,225]
        if r<70 and g<70 and b<70:
            dark.append(x)
    if dark:
        print(f"  dark x {min(dark)}-{max(dark)} width {max(dark)-min(dark)+1}")

